<?php
require_once __DIR__ . '/../includes/functions.php'; require_role(['admin','staff']); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$contact=trim($_POST['contact_name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');$id=(int)($_POST['id']??0);if($name==='')$error='Supplier name is required.';else{if($id){$s=$conn->prepare('UPDATE suppliers SET name=?,contact_name=?,phone=?,email=?,address=? WHERE id=?');$s->bind_param('sssssi',$name,$contact,$phone,$email,$address,$id);}else{$s=$conn->prepare('INSERT INTO suppliers(name,contact_name,phone,email,address) VALUES(?,?,?,?,?)');$s->bind_param('sssss',$name,$contact,$phone,$email,$address);}$s->execute();log_activity($conn,$id?'UPDATE':'CREATE','suppliers',$id?:$conn->insert_id,'Supplier saved');flash('success','Supplier saved.');redirect('admin/suppliers.php');}}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$conn->prepare('SELECT * FROM suppliers WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}
layout_header('Suppliers');
?>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="grid two section-gap"><section class="card"><h2><?= $edit?'Edit':'Add' ?> supplier</h2><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Business/name<input name="name" required value="<?= e($edit['name']??'') ?>"></label><label>Contact person<input name="contact_name" value="<?= e($edit['contact_name']??'') ?>"></label><label>Phone<input name="phone" value="<?= e($edit['phone']??'') ?>"></label><label>Email<input type="email" name="email" value="<?= e($edit['email']??'') ?>"></label><label>Address<textarea name="address"><?= e($edit['address']??'') ?></textarea></label><button class="btn">Save supplier</button></form></section><section class="card"><h2>Supplier list</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Phone</th><th></th></tr></thead><tbody><?php $q=$conn->query('SELECT * FROM suppliers ORDER BY name');while($s=$q->fetch_assoc()): ?><tr><td><?= e($s['name']) ?></td><td><?= e($s['contact_name']) ?></td><td><?= e($s['phone']) ?></td><td><a class="btn btn-small btn-action btn-edit" href="?edit=<?= $s['id'] ?>">Edit</a></td></tr><?php endwhile; ?></tbody></table></div></section></div>
<?php layout_footer(); ?>
